; --- 0x011511-0x011518  EGEnv_ModeBits_Table -- 4 u16 {0x0000, 0xC000, 0x4000, 0x8000}
; EGEnv_Compute_*_FormatBits OR the entry selected by (rec+0x00) & 3 into the
; computed envelope word; also used by the Voice_Freq_Write* stores and
; DSP_ChanFreq_WritePacket1 (2*descriptor[0x60]) -- the 2-bit envelope/format
; mode field, pre-shifted into bits 14..15.
EGEnv_ModeBits_Table:
	.short 0x0000, 0xc000, 0x4000, 0x8000

