; --- 0x0131cf-0x0133ce  128 x u32 monotonic gain curve, read by DSP_MixerCoeff_Compute:
; g = curve[index] >> 15 enters the Q15/Q16 two-stage mixer-gain product that lands in
; DSP2 (MN19413) registers 0xd0/0xd3.  Piecewise-exponential with four splice points,
; ending exactly at digital full scale 0x7fffff00 (0x7fffff << 8):
;     index   0- 25  ratio 1.1521423/step = 1.2301 dB  (max rel. residual 1.2e-7)
;     index  25-103  ratio 1.0321703/step = 0.2750 dB  (max rel. residual 3.9e-7)
;     index 103-115  ratio 1.0110333/step = 0.0953 dB  (max rel. residual 4.7e-8)
;     index 115-127  ratio 1.0016133/step = 0.0140 dB  (max rel. residual 8.1e-8)
; Total span 53.5 dB.  NOTE for the 2026-08 audit: the "exponential pitch table at
; 0x13318" is the MIDDLE of this curve -- 0x13318 is where the audit's 24-bit-masked
; monotonicity scan happened to lock on, not a table boundary.  Read as pitch the middle
; segment would be 54.82 cents/step; it matches neither 2^(n/256) (4.69 cents/step) nor
; any whole-cent law, and the only proven consumer treats entries as amplitude, not pitch.
DSP_MixerGain_Curve:
	.long 0x00451eb3, 0x004fa2d0, 0x005bc083, 0x0069b61b
